From 7ac18f00ff442bf3c318f66fe1da253582af95ff Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:41:53 +0100
Subject: [PATCH] applets/kickoff: hide the Favorites category when it is empty

Kickoff always opened on the Favorites category, even when there were no
favorites and the page was blank. Now the category is hidden while empty
and All Applications is shown instead; it reappears while dragging an app.

BUG: 474390
---
 applets/kickoff/ApplicationsPage.qml | 10 ++++++++++
 applets/kickoff/KickoffListView.qml  | 13 +++++++------
 2 files changed, 17 insertions(+), 6 deletions(-)

diff --git a/applets/kickoff/ApplicationsPage.qml b/applets/kickoff/ApplicationsPage.qml
index 76a058faec..a85e63ac96 100644
--- a/applets/kickoff/ApplicationsPage.qml
+++ b/applets/kickoff/ApplicationsPage.qml
@@ -52,11 +52,21 @@ BasePage {
         focus: true // needed for Loaders
         model: kickoff.rootModel
         isSidebar: true
+        firstIndex: kickoff.rootModel.favoritesModel.count > 0 ? 0 : 1
+        onFirstIndexChanged: {
+            if (!kickoff.expanded || currentIndex < firstIndex) {
+                currentIndex = firstIndex
+            }
+        }
         // needed otherwise app displayed at top-level will show a first character as group.
         section.property: ""
         delegate: KickoffListDelegate {
             id: sideBarDelegate
+            // Keep an empty Favorites category visible while dragging, so apps can be dropped onto it
+            readonly property bool hidden: sideBarDelegate.index < sideBar.firstIndex && !kickoff.dragSource.sourceItem
             width: view.availableWidth
+            height: hidden ? 0 : implicitHeight
+            visible: !hidden
             isCategoryListItem: true
             background: PlasmaExtras.Highlight {
                 // I have to do this for it to actually fill the item for some reason
diff --git a/applets/kickoff/KickoffListView.qml b/applets/kickoff/KickoffListView.qml
index 839ea277e8..4d36cec525 100644
--- a/applets/kickoff/KickoffListView.qml
+++ b/applets/kickoff/KickoffListView.qml
@@ -33,6 +33,7 @@ EmptyPage {
     property alias highlight: view.highlight
     property alias view: view
     property bool isSidebar: false
+    property int firstIndex: 0

     property bool mainContentView: false
     property bool hasSectionView: false
@@ -113,7 +114,7 @@ EmptyPage {
         leftMargin: kickoff.backgroundMetrics.leftPadding
         rightMargin: kickoff.backgroundMetrics.rightPadding

-        currentIndex: count > 0 ? 0 : -1
+        currentIndex: count > root.firstIndex ? root.firstIndex : -1
         focus: true
         interactive: height < contentHeight
         pixelAligned: true
@@ -130,7 +131,7 @@ EmptyPage {

         onCountChanged: {
             if (!activeFocus) {
-                currentIndex = (count > 0 ? 0 : -1)
+                currentIndex = (count > root.firstIndex ? root.firstIndex : -1)
             } else if (count > 0 && currentIndex !== -1) {
                 positionViewAtIndex(currentIndex, ListView.Contain)
             }
@@ -201,7 +202,7 @@ EmptyPage {
             target: kickoff
             function onExpandedChanged() {
                 if (!kickoff.expanded) {
-                    view.currentIndex = 0
+                    view.currentIndex = root.firstIndex
                     view.positionViewAtBeginning()
                 }
             }
@@ -264,7 +265,7 @@ EmptyPage {
             const targetX = currentItem ? currentItem.x : contentX
             let targetY = currentItem ? currentItem.y : contentY
             let targetIndex = currentIndex
-            const atFirst = currentIndex === 0
+            const atFirst = currentIndex <= root.firstIndex
             const atLast = currentIndex === count - 1
             if (count >= 1 || (kickoff.runnerModel.querying && [Qt.Key_Return, Qt.Key_Enter].includes(event.key))) {
                 switch (event.key) {
@@ -295,7 +296,7 @@ EmptyPage {
                         focusCurrentItem(event, Qt.TabFocusReason)
                     } break
                     case Qt.Key_Home: if (!atFirst) {
-                        currentIndex = 0
+                        currentIndex = root.firstIndex
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
                     case Qt.Key_End: if (!atLast) {
@@ -310,7 +311,7 @@ EmptyPage {
                             targetY += 1
                             targetIndex = indexAt(targetX, targetY)
                         }
-                        currentIndex = Math.max(targetIndex, 0)
+                        currentIndex = Math.max(targetIndex, root.firstIndex)
                         focusCurrentItem(event, Qt.BacktabFocusReason)
                     } break
                     case Qt.Key_PageDown: if (!atLast) {
-- 
